/**
 * OWL Editorial Content — Image Upload + Body Update Script
 *
 * Reads the manifest generated by the import session
 * (scripts/import-reports/owl_import_manifest.json), then for each record:
 *   1. Re-extracts the embedded image from the original DOCX file
 *   2. Uploads the image to Supabase Storage (media-uploads bucket)
 *   3. UPDATE content_posts SET body = ..., featured_image = <url> WHERE slug = ...
 *
 * Run from the repo root:
 *   node scripts/upload-images-and-update-bodies.mjs
 *   node scripts/upload-images-and-update-bodies.mjs --dry-run
 *   node scripts/upload-images-and-update-bodies.mjs --bodies-only
 *   node scripts/upload-images-and-update-bodies.mjs --images-only
 *   node scripts/upload-images-and-update-bodies.mjs --slug potty-training-regression-and-accidents
 *
 * Prerequisites:
 *   - .env.local with NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY
 *   - Node 18+
 *   - scripts/import-reports/owl_import_manifest.json (created by import session)
 *   - Original DOCX source files accessible on this machine
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');

// ── Config ────────────────────────────────────────────────────────────────────

const MANIFEST_PATH = path.join(REPO_ROOT, 'scripts', 'import-reports', 'owl_import_manifest.json');

const NEWS_DIR = path.join(
  'C:\\Users\\Ricko\\OneDrive\\Desktop\\OWL Sing Together',
  'OWL News Articles',
  'Sept -Oct Articles'
);
const BLOGS_DIR = path.join(
  'C:\\Users\\Ricko\\OneDrive\\Desktop\\OWL Sing Together',
  'OWL Blogs',
  'Sept - Oct Blogs'
);

const STORAGE_BUCKET = 'media-uploads';
const STORAGE_PREFIX = 'editorial/';

// ── CLI args ──────────────────────────────────────────────────────────────────

const args = process.argv.slice(2);
const DRY_RUN     = args.includes('--dry-run');
const BODIES_ONLY = args.includes('--bodies-only');
const IMAGES_ONLY = args.includes('--images-only');
const slugFilter  = (() => { const i = args.indexOf('--slug'); return i >= 0 ? args[i+1] : null; })();

// ── Load .env.local ───────────────────────────────────────────────────────────

function loadEnv() {
  const envPath = path.join(REPO_ROOT, '.env.local');
  if (!fs.existsSync(envPath)) throw new Error('.env.local not found at ' + envPath);
  for (const line of fs.readFileSync(envPath, 'utf8').split('\n')) {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
    if (m) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
}

// ── Supabase helpers ──────────────────────────────────────────────────────────

function supabaseHeaders() {
  return {
    apikey: process.env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal',
  };
}

async function uploadImage(fileName, imageBuffer, mimeType) {
  const storageKey = `${STORAGE_PREFIX}${fileName}`;
  const url = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/${STORAGE_BUCKET}/${storageKey}`;

  const resp = await fetch(url, {
    method: 'POST',
    headers: {
      apikey: process.env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Type': mimeType,
      'x-upsert': 'true',
    },
    body: imageBuffer,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`Storage upload failed (${resp.status}): ${text}`);
  }

  // Build public URL
  const publicUrl = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/${STORAGE_BUCKET}/${storageKey}`;
  return publicUrl;
}

async function updatePost(slug, { body, featuredImage, imagesOnly, bodiesOnly }) {
  const updates = {};
  if (!imagesOnly && body !== undefined) updates.body = body;
  if (!bodiesOnly && featuredImage !== undefined) updates.featured_image = featuredImage;
  if (Object.keys(updates).length === 0) return;

  const url = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/content_posts?slug=eq.${encodeURIComponent(slug)}`;
  const resp = await fetch(url, {
    method: 'PATCH',
    headers: supabaseHeaders(),
    body: JSON.stringify(updates),
  });
  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`DB update failed for slug=${slug} (${resp.status}): ${text}`);
  }
}

// ── DOCX image extractor ──────────────────────────────────────────────────────

/**
 * Extracts the first embedded image from a DOCX file using mammoth.
 * Returns { buffer, ext, mimeType } or null if no image found.
 */
async function extractDocxImage(docxPath) {
  try {
    const mammoth = await import('mammoth');
    const images = [];

    await mammoth.convertToHtml(
      { path: docxPath },
      {
        convertImage: mammoth.images.imgElement(async (image) => {
          if (images.length === 0) {
            const buffer = await image.read();
            const contentType = image.contentType || 'image/png';
            const extMap = { 'image/png': '.png', 'image/jpeg': '.jpg', 'image/gif': '.gif', 'image/webp': '.webp' };
            const ext = extMap[contentType] || '.png';
            images.push({ buffer: Buffer.from(buffer), ext, mimeType: contentType });
          }
          return { src: '' };
        }),
      }
    );

    return images.length > 0 ? images[0] : null;
  } catch (err) {
    return null;
  }
}

// ── Find DOCX file ────────────────────────────────────────────────────────────

function findDocxForRecord(record) {
  const dir = record.content_type === 'news' ? NEWS_DIR : BLOGS_DIR;
  if (!fs.existsSync(dir)) return null;
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.docx') && !f.startsWith('~$'));

  // Try to match by slug keywords derived from the filename
  const slugWords = record.slug.split('-');
  // Verbatim slug pattern: "why-toddlers-say-no" → "why_toddlers_say_no" or "why toddlers say no"
  const slugVerbatim = record.slug.replace(/-/g, '_');
  let bestMatch = null;
  let bestScore = 0;

  for (const file of files) {
    const nameLower = file.toLowerCase().replace(/[^a-z0-9]/g, ' ');
    const nameUnderscore = file.toLowerCase().replace(/[^a-z0-9]/g, '_');

    // Perfect match: full slug appears verbatim in the filename (e.g. why_toddlers_say_no)
    if (nameUnderscore.includes(slugVerbatim)) {
      return path.join(dir, file);
    }

    let score = 0;
    for (const word of slugWords) {
      if (word.length > 3 && nameLower.includes(word)) score++;
    }
    if (score > bestScore) {
      bestScore = score;
      bestMatch = file;
    }
  }

  if (bestScore < 2) return null; // Not confident enough
  return path.join(dir, bestMatch);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  loadEnv();

  if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error('Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY in .env.local');
  }

  if (!fs.existsSync(MANIFEST_PATH)) {
    throw new Error(`Manifest not found: ${MANIFEST_PATH}\nRun the import session first.`);
  }

  const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
  let records = manifest.records;

  if (slugFilter) {
    records = records.filter(r => r.slug === slugFilter);
    if (records.length === 0) throw new Error(`No record found with slug: ${slugFilter}`);
  }

  console.log(`\n=== OWL Image Upload + Body Update ===`);
  console.log(`Records to process: ${records.length}`);
  console.log(`Mode: ${DRY_RUN ? 'DRY-RUN' : 'LIVE'} | ${BODIES_ONLY ? 'bodies-only' : IMAGES_ONLY ? 'images-only' : 'full'}`);
  if (DRY_RUN) console.log(`(No changes will be made)\n`);

  const results = { success: 0, imageUploaded: 0, bodyUpdated: 0, imageSkipped: 0, errors: [] };

  for (let i = 0; i < records.length; i++) {
    const r = records[i];
    const prefix = `[${i+1}/${records.length}] ${r.content_type}/${r.slug}`;
    process.stdout.write(`${prefix} ... `);

    try {
      let featuredImageUrl = undefined;

      // ── Image upload ──────────────────────────────────────────────────────
      if (!BODIES_ONLY) {
        const docxPath = findDocxForRecord(r);
        if (!docxPath) {
          process.stdout.write(`(no DOCX match, skipping image) `);
          results.imageSkipped++;
        } else {
          const imageData = await extractDocxImage(docxPath);
          if (!imageData) {
            process.stdout.write(`(no image in DOCX, skipping) `);
            results.imageSkipped++;
          } else {
            // Build storage filename: use content_type prefix for the known collision
            let storageFilename;
            if (r.slug === 'teaching-sharing-and-turn-taking' || r.slug === 'sharing-and-turn-taking-for-children') {
              storageFilename = `${r.content_type}-${r.slug}${imageData.ext}`;
            } else {
              storageFilename = `${r.slug}${imageData.ext}`;
            }

            if (DRY_RUN) {
              process.stdout.write(`[DRY] would upload ${storageFilename} (${imageData.buffer.length} bytes) `);
              featuredImageUrl = `[DRY]/${storageFilename}`;
            } else {
              featuredImageUrl = await uploadImage(storageFilename, imageData.buffer, imageData.mimeType);
              process.stdout.write(`uploaded(${Math.round(imageData.buffer.length/1024)}KB) `);
              results.imageUploaded++;
            }
          }
        }
      }

      // ── Body update ───────────────────────────────────────────────────────
      if (!IMAGES_ONLY) {
        if (!r.body_html || r.body_html.trim() === '') {
          process.stdout.write(`(no body HTML) `);
        } else if (DRY_RUN) {
          process.stdout.write(`[DRY] would update body(${r.body_html.length}chars) `);
        } else {
          await updatePost(r.slug, { body: r.body_html, featuredImage: featuredImageUrl, imagesOnly: IMAGES_ONLY, bodiesOnly: BODIES_ONLY });
          process.stdout.write(`body-updated `);
          results.bodyUpdated++;
        }
      } else if (featuredImageUrl && !DRY_RUN) {
        // images-only mode — update just featured_image
        await updatePost(r.slug, { featuredImage: featuredImageUrl, imagesOnly: true, bodiesOnly: false });
      }

      results.success++;
      console.log(`✓`);
    } catch (err) {
      console.log(`ERROR: ${err.message}`);
      results.errors.push({ slug: r.slug, error: err.message });
    }
  }

  // ── Summary ───────────────────────────────────────────────────────────────
  console.log(`\n=== Summary ===`);
  console.log(`Processed:      ${results.success}/${records.length}`);
  console.log(`Images uploaded: ${results.imageUploaded}`);
  console.log(`Images skipped:  ${results.imageSkipped}`);
  console.log(`Bodies updated:  ${results.bodyUpdated}`);
  console.log(`Errors:          ${results.errors.length}`);
  if (results.errors.length > 0) {
    console.log('\nFailed records:');
    for (const e of results.errors) console.log(`  - ${e.slug}: ${e.error}`);
  }

  // Save report
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const reportDir = path.join(REPO_ROOT, 'scripts', 'import-reports');
  fs.mkdirSync(reportDir, { recursive: true });
  const reportPath = path.join(reportDir, `upload-report-${timestamp}.json`);
  fs.writeFileSync(reportPath, JSON.stringify({ timestamp, dryRun: DRY_RUN, results }, null, 2));
  console.log(`\nReport saved: ${reportPath}`);
}

main().catch(err => {
  console.error('\nFatal error:', err.message);
  process.exit(1);
});
